      note: '募集定員枠40%程度(各科)。A型(各科の特色について深く理解し各科の望む生徒像の体得に強い意欲があり他の模範となる生徒)とB型(各科の特色について深く理解し募集要項で定める部活動で中学校時代の活動実績又は高い技術を持ち入学後も継続して活動する生徒)がある。求める生徒像は機関士の資格を取得し大型船舶の機関長や機関士を目指す生徒、二級ボイラ・危険物取扱者・溶接関係の資格取得に積極的に取り組む生徒。学力検査は5教科で満点250点。調査書は各教科135点+特別活動等・長所特技等55点で合計190点満点(部活動や地域クラブ活動等の実績や取組内容などは総合的に評価し点数化)。特色面接は個人面接で本校の各科で学ぶ意欲や自らの考えをまとめ適切に伝える表現力をみて点数化し100点満点。特色検査はA型=作文(あるテーマについて600字程度で自分の考えを述べる・点数化して260点満点)、B型=実技(各種の技術・技能をみる・点数化して260点満点)。選抜資料の満点はA型・B型とも800点',
